    day6ReturnCard: '<h3 data-i18n="returnPolignanoHeading">🚐 RETURN TO POLIGNANO A MARE</h3><p>19:00 departure<br>20:00 arrival</p><hr><p><strong>20:00 – Dinner</strong></p>',
