    day8WeatherLink: '🌤 Check Ostuni weather',
    day8MapCard: '<h3 data-i18n="routeMapHeading">🗺️ Route map</h3><img id="mapa-image" src="images/mapaHdia8.jpg" alt="Route map" style="width: 100%; max-width: 900px; height: auto; border: 0; border-radius: 10px;" loading="lazy">',
    day8StrategicCard: '<h3 data-i18n="day8StrategicHeading">🚐 STRATEGIC DEPARTURE</h3><p><strong>08:30 - Departure from the hotel in Polignano a Mare</strong></p><p>✔ Leaving early is KEY.<br>It allows arrival before tourist groups.</p><p><strong>09:25 - Arrival in Ostuni</strong></p><p>The minibus drops the group at the authorized parking below the historic center.</p><p>✔ Walk up or use an Ape Calessino.</p>',
