    day9InfoCard: '<h3 data-i18n="generalInfoHeading">🏨 General information</h3><p><strong>Departure base:</strong> Polignano a Mare<br><strong>Distance:</strong> 101 km<br><strong>Transfer time:</strong> ~1h45<br><strong>Service:</strong> 09:00–18:00<br><strong>Walking level:</strong> Moderate-high (stone stairs)</p>',
    day9MapCard: '<h3 data-i18n="routeMapHeading">🗺️ Route map</h3><img id="mapa-image" src="images/mapaIdia9.jpg" alt="Route map" style="width: 100%; max-width: 900px; height: auto; border: 0; border-radius: 10px;" loading="lazy">',
    day9TransferCard: '<h3 data-i18n="day9TransferHeading">🚐 STRATEGIC TRANSFER</h3><p><strong>09:00 - Departure from the hotel in Polignano a Mare</strong></p><p>✔ Comfortable drive on inland roads.</p><p><strong>10:45 - Arrival in Matera (authorized parking area)</strong></p><p>The minibus does not enter the historic center.</p><p>✔ Drop-off at authorized point + transfer on foot or by tuk-tuk.</p><p>👉 Recommended: leave luggage at the hotel and start with a light walk.</p>',
    day9MorningCard: '<h3 data-i18n="day9MorningHeading">🌞 MORNING – HISTORICAL INTRODUCTION</h3><p><strong>11:00 – 13:30</strong> including Piazza Vittorio Veneto, Palombaro Lungo, Casa Noha and first walk in Sasso Barisano.</p>',
