    day9AfternoonCard: '<h3 data-i18n="day9AfternoonHeading">🏛 AFTERNOON – DEEPER SASSI</h3><p>15:00 – 17:45 through Sasso Caveoso, Casa Grotta, Santa Maria de Idris and panoramic viewpoints.</p>',
