    day6InfoCard: '<h3 data-i18n="generalInfoHeading">🏨 Informazioni generali</h3><p><strong>Base:</strong> Cala Ponte Hotel (Marriott) – Polignano a Mare<br><strong>Tipo di giornata:</strong> culturale + panoramica<br><strong>Livello camminata:</strong> 🟡 moderato</p>',
    day6MapCard: '<h3 data-i18n="day6MapHeading">🗺️ Mappa del percorso</h3><img id="mapa-image" src="images/mapaFdia6.jpg" alt="Mappa del percorso" style="width: 100%; max-width: 900px; height: auto; border: 0; border-radius: 10px;" loading="lazy">',
