function applyTranslations(lang) {
  const dict = translations[lang] || translations.es;

  const translatePass = () => {
    document.querySelectorAll('[data-i18n]').forEach(element => {
      const key = element.getAttribute('data-i18n');
      if (dict[key]) {
        element.innerHTML = dict[key];
      }
    });
  };

  document.documentElement.lang = lang;
  document.title = dict.pageTitle;

  translatePass();
  translatePass();

  document.querySelectorAll('h1, h2, h3').forEach(element => {
    if (element.hasAttribute('data-i18n')) {
      return;
    }

    const fallback = dict.headingFallbacks?.[element.textContent.trim()];
    if (fallback) {
      element.textContent = fallback;
    }
  });

  const topMenuItems = document.querySelectorAll('.sidebar > .day-link');
  topMenuItems[0] && (topMenuItems[0].textContent = dict.menuHome);
  topMenuItems[1] && (topMenuItems[1].textContent = dict.menuItinerary);
  topMenuItems[2] && (topMenuItems[2].textContent = dict.menuTransport);
  topMenuItems[3] && (topMenuItems[3].textContent = dict.menuHotels);

  document.querySelectorAll('.day-group-label').forEach((element, index) => {
    const label = dict.dayGroupLabels?.[index] || dict.dayLabels?.[index];
    if (label) {
      element.textContent = label;
    }
  });

  document.querySelectorAll('.day-group').forEach(group => {
    const links = group.querySelectorAll('.submenu .day-link');
    if (links[0]) links[0].textContent = dict.activities;
    if (links[1]) links[1].textContent = dict.restaurants;
  });

  document.querySelectorAll('.back-btn').forEach(button => {
    button.textContent = dict.backToHome;
  });

  document.querySelectorAll('.lang-btn').forEach(button => {
    button.classList.toggle('active', button.getAttribute('data-lang') === lang);
  });

  refreshDayLabels();
  updateTourCountdown(lang);
  
}

const LANGUAGE_STORAGE_KEY = "triptoitaly.language";

function getSavedLanguage() {
  try {
    const lang = localStorage.getItem(LANGUAGE_STORAGE_KEY);
    return ["es", "en", "it"].includes(lang) ? lang : null;
  } catch (error) {
    console.warn("Unable to read saved language preference.", error);
    return null;
  }
}

function saveLanguage(lang) {
  try {
    if (["es", "en", "it"].includes(lang)) {
      localStorage.setItem(LANGUAGE_STORAGE_KEY, lang);
    }
  } catch (error) {
    console.warn("Unable to save language preference.", error);
  }
}

function clearSavedLanguage() {
  localStorage.removeItem(LANGUAGE_STORAGE_KEY);
}

document.querySelectorAll('.lang-btn').forEach(button => {
  button.addEventListener('click', () => {
    const lang = button.getAttribute('data-lang');
    applyTranslations(lang);
    saveLanguage(lang);
  });
});
